head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.dma_question = {};
scwin.dma_answer = {};

// 질문, 답변 데이터 전역변수

///////// 2. 초기화 영역 /////////
scwin.onpageload = async function() {
    try {
        let contnId = $c.data.getParameter("contnId");
        dma_QnaReq.set("contnId", contnId);
        const sbmOptions = {
            id : "sbm_SelectQnaList",
            action : "/api/discls/support/qna/dtl/select-list",
            method : "get",
            ref : "dma_QnaReq",
            target : "dtl_QnaListRes=body",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_SelectQnaList_submitdone(sbmRtn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL17302.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/// EVENT ///

/**
 * 질문 첨부파일 클릭
 */
scwin.txt_quesAttachFileNm_onclick = function (e) {
    try {
        let contnId = scwin.dma_question.contnId;
        let contnAttachSeq = scwin.dma_question.contnAttachSeq;
    	scwin.fileDown(contnId, contnAttachSeq);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL17302.txt_quesAttachFileNm_onclick" });
    }
};

/**
 * 답변 첨부파일 클릭
 */
scwin.txt_ansAttachFileNm_onclick = function (e) {
    try {
        let contnId = scwin.dma_answer.contnId;
        let contnAttachSeq = scwin.dma_answer.contnAttachSeq;
    	scwin.fileDown(contnId, contnAttachSeq);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL17302.txt_ansAttachFileNm_onclick" });
    }
};

/**
 * 수정 버튼 클릭
 */
scwin.btn_update_onclick = function (e) {
	try {
		const moveUrl = "/ui/dis/support/JLDFIL17301.xml";
	    let param = {};
	    param.contnId = dma_QnaReq.get("contnId");

	    $c.win.moveUrl(moveUrl, param);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "JLDFIL17302.btn_update_onclick" });
	}
};

/**
 * 삭제 버튼 클릭
 */
scwin.btn_delete_onclick = async function (e) {
    try {
        let contnId = dma_QnaReq.get("contnId");
        let actionUrl = "/api/discls/support/qna/delete?contnId="+contnId;
        $c.sbm.setAction(sbm_DeleteQna, actionUrl);
        const sbmOptions = {
            id : "sbm_DeleteQna",
            action : "/api/discls/support/qna/delete",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        scwin.sbm_DeleteQna_submitdone(sbmRtn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "JLDFIL17302.btn_delete_onclick" });
    }
};

/**
 * 목록 버튼 클릭
 */
scwin.btn_list_onclick = function (e) {
    try {
        const moveUrl = "/ui/dis/support/JLDFIL17300.xml";
        $c.win.moveUrl(moveUrl, {});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "JLDFIL17302.btn_list_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/// SUBMISSION ///

/**
 * 질문,답변 조회 후 데이터 세팅 및 렌더링
 */
scwin.sbm_SelectQnaList_submitdone = function (e) {
    const res = e.responseJSON;
    const bodyList = res.body;

    for (let i = 0; i < bodyList.length; i++){
        let resBody = bodyList[i];
        if(resBody.quesAnsTpCd === "1") { // 질문 data
            scwin.dma_question = resBody;

        } else if(resBody.quesAnsTpCd === "2") { // 답변 data
            scwin.dma_answer = resBody;
        }
    }

    scwin.setFormData();
};

/**
 * 삭제 완료 후 목록으로 이동
 */
scwin.sbm_DeleteQna_submitdone = function (e) {
	const moveUrl = "/ui/dis/support/JLDFIL17300.xml";
    $c.win.moveUrl(moveUrl, {});
};

///////// 5. 일반/업무 함수 영역 /////////
/// FUNCTION ///

/**
 * 화면에 데이터 세팅
 */
scwin.setFormData = function () {

    // 질문 영역 데이터 세팅
    if(scwin.dma_question.contnId) {
        txt_comNm.setValue(scwin.dma_question.comNm);
        txt_questrNm.setValue(scwin.dma_question.questrNm);
        txt_regDdtm.setValue(scwin.dma_question.regDdtm);

        // 질문영역 데이터 세팅
        txt_quesTitle.setValue("Q."+scwin.dma_question.quesTitle); // TODO: 이미지 필요
        txt_quesContn.setValue(scwin.dma_question.quesContn);

        // 첨부파일
        if(!scwin.dma_question.attachFileNm) {
            grp_quesAttach.hide();
        } else {
            let fileNm = ""; // attachIcon //TODO: 이미지 필요
            fileNm += scwin.dma_question.attachFileNm;
            txt_quesAttachFileNm.setValue(fileNm);
            grp_quesAttach.show("");
        }
    } else {
        grp_quesInfo.hide();
        grp_question.hide();
    }

    // 답변영역 데이터 세팅
    if(scwin.dma_answer.contnId) {
        grp_answer.show("");
        grp_answerInfo.show("");

        txt_ansTitle.setValue("A."+scwin.dma_answer.quesTitle); // TODO: 이미지 필요
        txt_ansContn.setValue(scwin.dma_answer.quesContn);

        // txt_ansInfo
        let answerInfo = scwin.dma_answer.questrNm;
        if(scwin.dma_answer.questrTelNo) {
            answerInfo += " (Tel."+scwin.dma_answer.questrTelNo+")";
        }
        txt_ansInfo.setValue(answerInfo);
        txt_ansRegDdtm.setValue(scwin.dma_answer.regDdtm);

        // 첨부파일
        if(!scwin.dma_answer.attachFileNm) {
            grp_ansAttach.hide();
        } else {
            let fileNm = ""; // attachIcon //TODO: 이미지 필요
            fileNm += scwin.dma_answer.attachFileNm;
            txt_ansAttachFileNm.setValue(fileNm);
            grp_ansAttach.show("");
        }
    } else {
        grp_answer.hide();
        grp_answerInfo.hide();
    }

    // 버튼 접근 권한
    let sessionId = $c.session.info("js_id");
    if(scwin.dma_question && scwin.dma_question.questrId === sessionId) { 
        btn_update.show("");
        btn_delete.show("");
    } else {
        btn_update.hide();
        btn_delete.hide();
    }
};

/**
 * 첨부파일 다운로드
 */
scwin.fileDown = function (contnId, contnAttachSeq) { 
    $p.download("/api/discls/support/qna/file/download?contnId="+contnId+"&contnAttachSeq="+contnAttachSeq, {}, "get", true);
};
